static int tda998x_audio_codec_init ( struct tda998x_priv * priv , struct device * dev ) { struct hdmi_codec_pdata codec_data = { . ops = & audio_codec_ops . max_i2s_channels = 2 } ; int i ; for ( i = 0 ; i < ARRAY_SIZE ( priv -> audio_port ) ; i ++ ) { if ( priv -> audio_port [ i ] . format == AFMT_SPDIF && priv -> audio_port [ i ] . config != 0 ) { codec_data . spdif = 1 ; } } priv -> audio_pdev = platform_device_register_data ( dev , HDMI_CODEC_DRV_NAME , PLATFORM_DEVID_AUTO , & codec_data , sizeof ( codec_data ) ) ; return PTR_ERR_OR_ZERO ( priv -> audio_pdev ) ; } 